import{_ as a}from"./chunks/architecture.Cs8uKTTN.js";import{_ as e,o as r,c as d,a2 as s}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"swag2mcp","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/index.md","filePath":"zh-CN/index.md","lastUpdated":1784903584000}'),n={name:"zh-CN/index.md"};function o(i,t,p,c,l,h){return r(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="swag2mcp" tabindex="-1">swag2mcp <a class="header-anchor" href="#swag2mcp" aria-label="Permalink to &quot;swag2mcp&quot;">​</a></h1><div style="background:#dc2626;color:white;padding:20px 24px;border-radius:12px;text-align:center;font-size:1.4em;font-weight:700;margin:24px 0;"> 🚧 开发中 — 即将发布！ </div><p>通过模型上下文协议（MCP）将 OpenAPI/Swagger/Postman API 规范与 LLM 智能体连接起来。</p><a href="https://www.youtube.com/watch?v=1Da4UmE2f9U" target="_blank"><img src="https://raw.githubusercontent.com/mmadfox/swag2mcp/main/docs/cover.png" alt="预览"></a><h2 id="你的-api-会说-llm-语言" tabindex="-1">你的 API 会说 LLM 语言 <a class="header-anchor" href="#你的-api-会说-llm-语言" aria-label="Permalink to &quot;你的 API 会说 LLM 语言&quot;">​</a></h2><p>一行配置即可将任何 OpenAPI/Swagger/Postman 文件转换为 MCP 服务器。LLM 智能体可以发现、检查和调用你的 API — 无需编写集成代码。</p><img src="'+a+'" width="700" alt="swag2mcp 架构"><h2 id="告别重复的包装代码" tabindex="-1">告别重复的包装代码 <a class="header-anchor" href="#告别重复的包装代码" aria-label="Permalink to &quot;告别重复的包装代码&quot;">​</a></h2><p>每次将新 API 连接到 LLM 时，你都要编写相同的样板代码：规范解析、认证、错误处理、速率限制。swag2mcp 为你完成这一切 — 19 个现成的 MCP 工具。</p><h2 id="谁需要它" tabindex="-1">谁需要它 <a class="header-anchor" href="#谁需要它" aria-label="Permalink to &quot;谁需要它&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>原因</th></tr></thead><tbody><tr><td><strong>AI 智能体开发者</strong></td><td>2 分钟连接任何 API，而不是 2 天</td></tr><tr><td><strong>MCP 工程师</strong></td><td>无需处理代码 — 只需指向规范即可</td></tr><tr><td><strong>架构师</strong></td><td>为公司所有 LLM 提供统一的 API 集成层</td></tr><tr><td><strong>数据分析师</strong></td><td>通过自然语言访问 API，无需编码</td></tr><tr><td><strong>DevOps / SRE</strong></td><td>通过 LLM 进行监控和自动化，无需额外服务</td></tr><tr><td><strong>集成工程师</strong></td><td>9 种开箱即用的认证方法 — 从 Basic 到 OAuth2 到 HMAC</td></tr><tr><td><strong>QA 工程师</strong></td><td>无需真实 API 即可进行隔离测试的模拟服务器</td></tr><tr><td><strong>产品经理</strong></td><td>无需后端工作即可快速构建 AI 功能原型</td></tr><tr><td><strong>以及其他许多人</strong></td><td></td></tr></tbody></table><hr><h2 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h2><p>基于 <strong>GNU Affero General Public License v3.0</strong>（AGPL v3）许可。</p><p>完整许可文本请参见 <a href="https://github.com/mmadfox/swag2mcp/blob/main/LICENSE" target="_blank" rel="noreferrer">LICENSE</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SPDX-License-Identifier: AGPL-3.0-only</span></span></code></pre></div>',16)])])}const P=e(n,[["render",o]]);export{b as __pageData,P as default};
